package com.secman.controller

import com.secman.service.CrowdStrikeImportRunLease
import com.secman.service.ImportCompletionNotifier
import com.secman.service.MaterializedViewRefreshService
import io.micronaut.http.HttpResponse
import io.micronaut.http.HttpStatus
import io.micronaut.http.annotation.Controller
import io.micronaut.http.annotation.Post
import io.micronaut.http.annotation.QueryValue
import io.micronaut.http.annotation.PathVariable
import io.micronaut.scheduling.TaskExecutors
import io.micronaut.scheduling.annotation.ExecuteOn
import org.slf4j.LoggerFactory
import io.micronaut.security.annotation.Secured
import io.micronaut.security.authentication.Authentication

@Controller("/api/crowdstrike/servers/import/runs")
@Secured("ADMIN", "VULN")
@ExecuteOn(TaskExecutors.BLOCKING)
open class CrowdStrikeImportRunController(
    private val lease: CrowdStrikeImportRunLease,
    private val notifier: ImportCompletionNotifier,
    private val refreshService: MaterializedViewRefreshService
) {
    private val log = LoggerFactory.getLogger(CrowdStrikeImportRunController::class.java)
    private fun actor(authentication: Authentication) = authentication.name.replace("\r", "").replace("\n", "")

    @Post
    @Synchronized
    open fun start(authentication: Authentication): HttpResponse<*> = try {
        val id = lease.start(authentication.name)
        notifier.beginExplicitRun(id)
        log.info("CrowdStrike import run started: runId={}, actor={}", id, actor(authentication))
        HttpResponse.ok(mapOf("runId" to id))
    } catch (e: IllegalStateException) {
        HttpResponse.status<Map<String, String>>(HttpStatus.CONFLICT)
            .body(mapOf("error" to "An import run is already active"))
    }

    @Post("/{runId}/heartbeat")
    open fun heartbeat(@PathVariable runId: String, authentication: Authentication): HttpResponse<*> = try {
        lease.heartbeat(runId, authentication.name)
        HttpResponse.ok(mapOf("status" to "ACTIVE"))
    } catch (e: IllegalStateException) {
        HttpResponse.status<Map<String, String>>(HttpStatus.CONFLICT)
            .body(mapOf("error" to "Import run is unavailable"))
    }

    @Post("/{runId}/finish")
    @Synchronized
    open fun finish(@PathVariable runId: String, @QueryValue(defaultValue = "false") successful: Boolean,
                    authentication: Authentication): HttpResponse<*> = try {
        lease.requireOwner(runId, authentication.name)
        notifier.finishExplicitRun(runId, successful)
        lease.finish(runId, authentication.name)
        log.info("CrowdStrike import run finished: runId={}, actor={}, successful={}", runId, actor(authentication), successful)
        refreshService.requestDeferredRefresh("CrowdStrike import run ended")
        HttpResponse.ok(mapOf("status" to if (successful) "COMPLETED" else "FAILED"))
    } catch (e: IllegalStateException) {
        HttpResponse.status<Map<String, String>>(HttpStatus.CONFLICT)
            .body(mapOf("error" to "Import run is unavailable"))
    }
}
package com.secman.service

import jakarta.inject.Singleton
import java.time.Clock
import java.time.Instant
import java.util.UUID

/** Bounds a CLI run's lifetime without interpreting pauses in Falcon requests as completion. */
@Singleton
class CrowdStrikeImportRunLease {
    internal var clock: Clock = Clock.systemUTC()
    private data class Run(val id: String, val owner: String, var expiresAt: Instant)
    private var run: Run? = null

    @Synchronized
    fun start(owner: String): String {
        check(active() == null) { "An import run is already active" }
        val id = UUID.randomUUID().toString()
        run = Run(id, owner, clock.instant().plusSeconds(600))
        return id
    }

    @Synchronized
    fun heartbeat(id: String, owner: String) {
        requireOwner(id, owner)
        run!!.expiresAt = clock.instant().plusSeconds(600)
    }

    @Synchronized
    fun requireOwner(id: String, owner: String) {
        val current = active()
        check(current != null && current.id == id && current.owner == owner) { "Import run is unavailable" }
    }

    @Synchronized
    fun finish(id: String, owner: String) {
        requireOwner(id, owner)
        run = null
    }

    @Synchronized
    fun activeRunId(): String? = active()?.id

    private fun active(): Run? {
        if (run?.expiresAt?.isAfter(clock.instant()) == false) run = null
        return run
    }
}
    }

    /**
     * Get recent refresh job history
     *
     * @param limit Maximum number of jobs to return
     * @return List of recent jobs, newest first
     */
    fun getRecentJobs(limit: Int = 10): List<MaterializedViewRefreshJob> {
        val pageable = Pageable.from(0, limit, Sort.of(Sort.Order.desc("startedAt")))
        return refreshJobRepository.findAll(pageable).content
    }

    /**
     * Drains a debounced refresh trigger once it's safe to start: no job currently
     * running, and the cooldown since the last completed cycle has elapsed. This is
     * what guarantees the latest trigger received during a burst (e.g. a long
     * CrowdStrike import posting many sub-batches) eventually runs, instead of being
     * permanently dropped by the cooldown gate in [triggerAsyncRefresh].
     *
     * 15s is intentionally much shorter than the cooldown itself, so the extra
     * staleness this sweep can introduce is bounded and negligible relative to the
     * cooldown — it isn't separately configurable to keep the config surface small.
     */
    @Scheduled(fixedDelay = "15s")
    open fun sweepPendingRefreshTrigger() {
