text(JSON.stringify(p.structuredContent||p,null,2));
const attackPath={
  decision:"ignore",
  impact:"medium",
  likelihood:"ignore",
  severity:"ignore",
  dataflow:"A caller who already has ADMIN or VULN authority starts POST /api/crowdstrike/servers/import/runs, receives the UUID, and repeatedly invokes the owner-bound heartbeat before each 600-second expiry. CrowdStrikeImportRunLease extends the process-local lease without an absolute deadline. While it remains active, the scheduled pending materialized-view refresh and inferred completion notification return early; other explicit runs receive a conflict.",
  reachability:"The component is in the product's authenticated HTTP surface and the path is statically reachable, but @Secured limits it to ADMIN/VULN. Owner and UUID checks prevent other principals from renewing the lease. The resulting stale views and delayed reporting cross operational user boundaries, but no privilege escalation, data disclosure, integrity bypass, or lower-privileged entry path is established.",
  counterevidence:"Strongest counterevidence is the privileged-only precondition: ADMIN/VULN are intentionally entrusted with global vulnerability imports and mutations. The lease recovers ten minutes after heartbeats stop, pending refresh work is retained, and ADMIN can invoke a manual refresh. These controls do not remove the reliability flaw, but they make it non-reportable as a security vulnerability under the required policy.",
  change_conditions:"Re-evaluate as reportable if the endpoint becomes reachable to a lower-privileged identity, if a VULN role is not considered a trusted global import operator, or if repository/deployment evidence establishes a material security or safety impact from stale views that warrants treating privileged insider denial as in scope.",
  severity_rationale:"Impact could be medium operationally because security views and import completion can remain stale, but the only demonstrated attacker already holds the intended global ADMIN/VULN import privilege and gains no additional authority. The final hard-suppression rule for privileged-only preconditions therefore sets likelihood and severity to ignore."
};
const r=await tools.mcp__codex_security__record_candidate_attack_paths({scanId,attackPaths:[{candidateId,attackPath}]});
text(JSON.stringify(r.structuredContent||r,null,2));
const q=await tools.mcp__codex_security__update_codex_security_scan_progress({scanId,phase:"attack_path",phaseItemsTotal:1,phaseItemsCompleted:1,phaseProgressUnit:"candidate_findings",reportableFindingsCount:0});
text(JSON.stringify(q.structuredContent||q,null,2));

