const threatModel={
 summary:"SecMan is a Micronaut/Kotlin security-management backend with an Astro/React browser client, Kotlin CLI, MCP tool surfaces, and a Go mobile relay. This diff review emphasizes CrowdStrike retrieval, streamed authenticated imports, reconciliation, reporting scope, and workgroup presentation.",
 assets:[
  "User identities, roles, JWT sessions, MFA/passkey state, and delegated MCP authority.",
  "Asset, vulnerability, exception, assessment, account-mapping, and integration-result confidentiality and integrity.",
  "CrowdStrike/provider credentials and imported security data.",
  "Import and reconciliation correctness, view freshness, completion reporting, and bounded resource use."
 ],
 trustBoundaries:[
  "Browser or CLI to REST: cookie or bearer authority crosses into secured controllers.",
  "Authenticated principal to row-scoped persistence: controller roles and AssetFilterService/repository predicates enforce authority.",
  "Privileged CLI to CrowdStrike import endpoints: ADMIN/VULN starts an owner-bound process-local lease and streams bounded batches.",
  "SecMan to CrowdStrike: encrypted client credentials obtain provider tokens and third-party JSON becomes candidate local state.",
  "Backend to MariaDB and optional DMZ relay: deployment secrets and versioned authenticated envelopes cross service boundaries."
 ],
 attackerCapabilities:[
  "Unauthenticated callers can reach only explicit anonymous endpoints and begin without a session or API key.",
  "Authenticated ordinary users can control endpoint parameters but must not cross roles or row-level grants.",
  "An authenticated VULN principal legitimately has global import and reconciliation authority; abuse within that grant is distinct from added authority.",
  "Provider responses can influence volume, metadata, timing, and imported content but are not assumed to control SecMan credentials.",
  "Deployment operators and principals already controlling ADMIN, host, database, or secrets are trusted high-authority actors."
 ],
 securityObjectives:[
  "Authenticate non-public operations and bind credentials to the intended principal.",
  "Enforce role and row-level authorization at every sensitive consumer.",
  "Restrict CrowdStrike mutation and reconciliation to intended roles while bounding batches, leases, deletion, retries, and refresh staleness.",
  "Keep credentials out of responses, logs, source, and JavaScript-readable storage.",
  "Preserve integrity and freshness across asynchronous imports, materialized views, notifications, and relay snapshots."
 ],
 assumptions:[
  "The modeled Git scope is the root SecMan repository; independent gitignored repositories under extensions are reviewed separately for contract drift.",
  "Production supplies non-default secrets and terminates TLS at the documented reverse proxy; live deployment values were not verified.",
  "The CrowdStrike import lease is process-local and global exclusivity therefore assumes the currently documented single-backend-instance deployment.",
  "Asset ownership is metadata, not an access grant, following SECURITY.md, docs/ARCHITECTURE.md, and AssetFilterService despite inconsistent README wording.",
  "The inspected shared CrowdStrike clients use fixed https://api.crowdstrike.com endpoints; region-derived baseUrl configuration is an architecture discrepancy, not a vulnerability finding.",
  "All conclusions are static and offline; services, secrets, database behavior, proxy behavior, provider compatibility, and E2E were not exercised."
 ]
};
const coverage={
 completeness:"complete",
 surfaces:[
  {id:"backend-core",summary:"12 changed backend controller, DTO, repository, projection, filter, lease, query, and import-service files",status:"reviewed",outcome:"One lease-renewal candidate validated; final attack-path policy ignored it because exploitation requires intended global ADMIN/VULN authority and adds no privilege."},
  {id:"services-cli-shared",summary:"14 changed backend service, CLI, and shared CrowdStrike client files",status:"reviewed",outcome:"No reportable vulnerability; authentication, bounded queues, provider parsing, refresh and notification interactions reviewed."},
  {id:"frontend-build-config",summary:"10 changed build, configuration, workgroup UI, and shared-build files",status:"reviewed",outcome:"No reportable vulnerability; server-side role and workgroup-scope enforcement checked for client actions."},
  {id:"owasp-static-gate",summary:"Six heuristic REVIEW matches from scripts/owasp-check.sh",status:"reviewed",outcome:"All resolved by source trace: role checks and row scope intact, repository queries parameter-bound, and the outbound URL match is localhost-only integration-test code."}
 ],
 explicitExclusions:[
  {path:"extensions/",reason:"Independent git repositories are outside the root working-tree diff; only the finalizer's static integration-contract comparison covered them."}
 ],
 deferred:[],
 resolvedDeferred:[],
 openQuestions:[],
 mode:"working_tree",
 inventoryStrategy:"Workbench generated the 36-item changed-file inventory for the pinned working-tree digest; every item received a review receipt.",
 includePaths:["."],
 excludePaths:["extensions/"],
 receiptRefs:["36/36 workbench review items","candidate-873db54b61484f57 validation and attack-path decision"]
};
const r=await tools.mcp__codex_security__record_codex_security_scan_draft({
 scanId,complete:true,threatModel,findings:[],coverage,
 scope:{
  summary:"Pinned working-tree diff against a63e9a778860f7ce7fe14de4f712a53f8c566287; all 36 generated review items reviewed.",
  includePaths:["."],
  excludePaths:["extensions/"],
  artifactsReviewed:["SECURITY.md","CLAUDE.md","36 changed-file review items","OWASP heuristic results"],
  validationMode:"Static source/control/sink trace",
  runtimeStatus:"not run",
  limitations:["No services, credentials, database, build, or E2E were used.","Independent extension repositories are not part of the root Git diff.","The final ignored lease concern remains an operational design risk for trusted ADMIN/VULN principals and multi-instance deployment."]
 }
});
